-- =============================================================================
-- V19 救援资源 —— 达梦 DM8 方言（Oracle 兼容，未实跑验证）
--   镜像自 h2/V19__rescue_resource.sql。本文件未经达梦实例实跑验证，按 DM8 语法编写，需上环境复核。
-- =============================================================================

-- V19 应急救援资源域真实数据源（救援装备 / 救援人员 / 救援车辆 / 消防队伍）。
-- 数据来源：frontend-scaffold/src/screen/lib/data/ 下 rescueEquipmentMock.ts、rescuePersonnelMock.ts、
-- rescueVehicleMock.ts、fireBrigadeMock.ts 的存量硬编码，按 mock 中 buildItem / buildSampleVehicle /
-- buildTeam 的生成规则展开为具体行，迁移后数值与文案语义保持不变。
-- 命名回避数据库保留字（value/command/group/count/status/type/level/left/top）：
--   KV 的取数列为 value_text；人员分组列为 person_group；计数列为 item_count / member_count；
--   状态列统一加域前缀（equipment_status / vehicle_status / equip_status）。
-- 筛选下拉项（中队 / 岗位 / 车辆类型 / 区域）一并入库 fac_rescue_option，含“全部”首项。
-- 种子规模：装备 35 条、人员 52 条、车辆 12 条（含乘员/随车装备/耗材/出动汇总子表）、消防队伍 8 条
-- （含队伍车辆 39 条、队伍人员 110 条、队伍装备 71 条）。

CREATE TABLE fac_rescue_equipment (
    id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    equip_name VARCHAR2(64) NOT NULL,
    squadron VARCHAR2(32) NOT NULL,
    quantity NUMBER(9) NOT NULL DEFAULT 0,
    leader_name VARCHAR2(32) NOT NULL,
    leader_phone VARCHAR2(32) NOT NULL,
    stock_quantity NUMBER(9) NOT NULL DEFAULT 0,
    equip_model VARCHAR2(128) NOT NULL,
    protection_type VARCHAR2(128),
    filter_canister VARCHAR2(64),
    max_continuous_use VARCHAR2(64),
    storage_location VARCHAR2(128),
    purchase_batch VARCHAR2(64),
    factory_validity_years VARCHAR2(32),
    remaining_validity VARCHAR2(32),
    last_inspection_date VARCHAR2(32),
    next_mandatory_maintenance_date VARCHAR2(32),
    equipment_status VARCHAR2(32),
    scrap_warning VARCHAR2(32),
    issue_registration VARCHAR2(128),
    spare_parts VARCHAR2(128),
    sort_no NUMBER(9) NOT NULL DEFAULT 0
);


CREATE TABLE fac_rescue_personnel (
    id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    person_name VARCHAR2(32) NOT NULL,
    squadron VARCHAR2(32) NOT NULL,
    person_role VARCHAR2(32) NOT NULL,
    sort_no NUMBER(9) NOT NULL DEFAULT 0
);


CREATE TABLE fac_rescue_option (
    id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    option_kind VARCHAR2(32) NOT NULL,
    option_label VARCHAR2(64) NOT NULL,
    sort_no NUMBER(9) NOT NULL DEFAULT 0
);


CREATE TABLE fac_rescue_vehicle (
    id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    plate VARCHAR2(32) NOT NULL,
    vehicle_type VARCHAR2(32) NOT NULL,
    squadron VARCHAR2(32) NOT NULL,
    leader_name VARCHAR2(32) NOT NULL,
    leader_phone VARCHAR2(32) NOT NULL,
    vehicle_status VARCHAR2(16) NOT NULL,
    business_name VARCHAR2(64) NOT NULL,
    vehicle_type_full VARCHAR2(64) NOT NULL,
    parking_location VARCHAR2(128),
    chassis_model VARCHAR2(64),
    manufacture_date VARCHAR2(32),
    inspection_expiry VARCHAR2(32),
    foam_tank_volume VARCHAR2(32),
    water_tank_volume VARCHAR2(32),
    max_water_flow VARCHAR2(32),
    foam_type VARCHAR2(32),
    last_maintenance_date VARCHAR2(32),
    next_maintenance_date VARCHAR2(32),
    total_mileage VARCHAR2(32),
    fault_record VARCHAR2(128),
    inspection_status VARCHAR2(32),
    sort_no NUMBER(9) NOT NULL DEFAULT 0
);


CREATE TABLE fac_rescue_vehicle_crew (
    id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    vehicle_id NUMBER(19) NOT NULL,
    member_role VARCHAR2(32) NOT NULL,
    member_name VARCHAR2(32) NOT NULL,
    phone VARCHAR2(32) NOT NULL,
    certificate VARCHAR2(128),
    duty_status VARCHAR2(32),
    sort_no NUMBER(9) NOT NULL DEFAULT 0
);


CREATE TABLE fac_rescue_vehicle_equipment (
    id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    vehicle_id NUMBER(19) NOT NULL,
    equip_name VARCHAR2(64) NOT NULL,
    quantity VARCHAR2(32) NOT NULL,
    equip_model VARCHAR2(64),
    next_check_date VARCHAR2(32),
    equipment_status VARCHAR2(32),
    storage_location VARCHAR2(128),
    sort_no NUMBER(9) NOT NULL DEFAULT 0
);


CREATE TABLE fac_rescue_vehicle_kv (
    id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    vehicle_id NUMBER(19) NOT NULL,
    kv_kind VARCHAR2(32) NOT NULL,
    kv_label VARCHAR2(64) NOT NULL,
    value_text VARCHAR2(128) NOT NULL,
    sort_no NUMBER(9) NOT NULL DEFAULT 0
);


CREATE TABLE fac_brigade_team (
    id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    team_name VARCHAR2(64) NOT NULL,
    area VARCHAR2(32) NOT NULL,
    member_count NUMBER(9) NOT NULL DEFAULT 0,
    leader_name VARCHAR2(32) NOT NULL,
    leader_phone VARCHAR2(32) NOT NULL,
    location VARCHAR2(128),
    longitude DOUBLE PRECISION,
    latitude DOUBLE PRECISION,
    description VARCHAR2(512),
    rescue_personnel NUMBER(9) NOT NULL DEFAULT 0,
    rescue_vehicles NUMBER(9) NOT NULL DEFAULT 0,
    sort_no NUMBER(9) NOT NULL DEFAULT 0
);


CREATE TABLE fac_brigade_vehicle (
    id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    team_id NUMBER(19) NOT NULL,
    plate VARCHAR2(32) NOT NULL,
    vehicle_type VARCHAR2(32) NOT NULL,
    vehicle_status VARCHAR2(16) NOT NULL,
    parking_location VARCHAR2(64),
    sort_no NUMBER(9) NOT NULL DEFAULT 0
);


CREATE TABLE fac_brigade_person (
    id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    team_id NUMBER(19) NOT NULL,
    person_name VARCHAR2(32) NOT NULL,
    person_role VARCHAR2(32) NOT NULL,
    person_group VARCHAR2(32) NOT NULL,
    phone VARCHAR2(32) NOT NULL,
    duty_status VARCHAR2(16) NOT NULL,
    sort_no NUMBER(9) NOT NULL DEFAULT 0
);


CREATE TABLE fac_brigade_equipment (
    id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    team_id NUMBER(19) NOT NULL,
    equip_name VARCHAR2(64) NOT NULL,
    category VARCHAR2(32) NOT NULL,
    item_count NUMBER(9) NOT NULL DEFAULT 0,
    unit VARCHAR2(16),
    equip_status VARCHAR2(16),
    storage_location VARCHAR2(64),
    sort_no NUMBER(9) NOT NULL DEFAULT 0
);


